/* One sheet, not a stack: a dialog opened from another one takes its place (same side, same shape) with a Back
   button, and closing it brings the one underneath back. The X closes the whole sheet. */
function makeDialog(options,drawer=false) {
  const under=[...document.querySelectorAll('dialog.pv-dialog[open]')].filter(d=>!d.classList.contains('is-covered')).pop();
  const dialog=(drawer||under?.classList.contains('pv-drawer')?Drawer:Modal)(options);
  if(under){
    dialog.classList.add('is-pushed');under.classList.add('is-covered');
    const head=dialog.querySelector('.pv-dialog-head');head.prepend(Button({label:'Back',icon:'chevron-left',variant:'ghost',size:'sm',className:'kura-back',onClick:()=>dialog.dismiss()}));
    const x=head.querySelector('.pv-button[aria-label^="Close"]');if(x)x.onclick=()=>{for(const d of [...document.querySelectorAll('dialog.pv-dialog[open]')].reverse())d.dismiss();};
    dialog.addEventListener('close',()=>under.classList.remove('is-covered'),{once:true});
  }
  dialog.addEventListener('close',()=>dialog.remove(),{once:true});dialog.open();return dialog;
}
