function pagedTable({rows,...props},pageSize=100) {
  let current=0;const root=el('div');
  function draw(){const start=current*pageSize;root.replaceChildren(Table({...props,rows:rows.slice(start,start+pageSize)}),el('div',{className:'pagination'},[text(rows.length?`${fmt(start+1)}–${fmt(Math.min(start+pageSize,rows.length))} of ${fmt(rows.length)}`:'0 results'),inline([Button({label:'Previous',icon:'chevron-left',size:'sm',disabled:current===0,onClick:()=>{current--;draw();}}),Button({label:'Next',icon:'chevron-right',size:'sm',disabled:start+pageSize>=rows.length,onClick:()=>{current++;draw();}})])]));}draw();return root;
}
function field(def,value) {
  const id=`kura-field-${++serial}`;let node;
  if(def.type==='unitmap'){
    const rows=el('div'),entries=[];
    const add=(name='',factor='')=>{const unit=Input({label:'Unit name',value:name,required:true,placeholder:'e.g. vial or box'}),amount=Input({label:'Number of base units',type:'number',value:/^[-+]?\d+(?:\.\d+)?e[+-]?\d+$/i.test(String(factor))&&Number.isSafeInteger(Number(factor))?String(Number(factor)):factor,min:0,step:'any',required:true});const entry={unit,amount};const row=el('div',{className:'unit-row'},[unit,amount,Button({label:'Remove unit',icon:'trash',iconOnly:true,variant:'ghost',onClick:()=>{entries.splice(entries.indexOf(entry),1);row.remove();}})]);entries.push(entry);rows.append(row);};
    Object.entries(value||{}).forEach(([name,factor])=>add(name,factor));
    node=el('div',{className:'pv-field wide'},[el('h3',{},def.label),text(def.help||'The base unit must have a factor of 1. Add explicit conversions for every purchase or consumption unit.'),rows,Button({label:'Add unit conversion',icon:'plus',onClick:()=>add()})]);
    node.read=()=>{const result={};for(const entry of entries){const name=entry.unit.control.value.trim(),factor=entry.amount.control.value;if(!name||!factor)throw new Error('Every unit conversion needs a name and a factor.');if(Object.hasOwn(result,name))throw new Error(`Unit ${name} appears more than once.`);if(!Number.isFinite(Number(factor))||Number(factor)<=0)throw new Error(`The conversion for ${name} must be greater than zero.`);result[name]=factor;}return result;};return node;
  }
  if(def.type==='select')node=Dropdown({id,label:def.label,options:typeof def.options==='function'?def.options():def.options,value:value??def.default??''});
  else if(def.type==='checkbox'){const control=el('input',{id,type:'checkbox',checked:!!value});node=el('div',{className:'check-field'},[control,el('label',{for:id},def.label)]);node.control=control;}
  else if(def.type==='textarea'||def.type==='json'){const control=el('textarea',{id,className:`pv-input ${def.type==='json'?'code-input':''}`,required:!!def.required,spellcheck:def.type==='json'?'false':'true'},def.type==='json'?JSON.stringify(value??def.default??{},null,2):value??def.default??'');node=el('div',{className:'pv-field'},[el('label',{className:'pv-label',for:id},def.label),control,def.help?text(def.help,'pv-help'):null]);node.control=control;}
  else node=Input({id,label:def.label,value:value??def.default??'',type:def.type||'text',required:!!def.required,help:def.help,placeholder:def.placeholder,min:def.min,step:def.type==='number'?'any':undefined,autocomplete:def.autocomplete});
  node.control.name=def.key;if(def.required)node.control.required=true;if(def.wide)node.classList.add('wide');if(def.onChange)node.control.addEventListener('change',()=>def.onChange(node.control.value));
  node.read=()=>{const v=node.control.value;if(def.type==='checkbox')return node.control.checked;if(def.type==='json'){try{return JSON.parse(v||'{}');}catch{throw new Error(`${def.label} must contain valid JSON.`);}}if(def.type==='number')return v===''?0:Number(v);if(def.type==='lines')return v.split(/[,\n]/).map(x=>x.trim()).filter(Boolean);return v.trim();};return node;
}
const SAVED={'item.save':'Item saved.','order.save':'Order saved.','order.status':'Order updated.','order.receive':'Received into stock.','location.save':'Location saved.','vendor.save':'Vendor saved.','rule.save':'Levels saved.','count.create':'Count started.','count.record':'Count recorded.','count.reconcile':'Count reconciled. The adjustment is in Activity.','reservation.create':'Stock reserved.','reservation.release':'Reservation released.','reservation.consume':'Reserved stock used.','setting.save':'Settings saved.','barcode.save':'Barcode linked.','lot.quarantine':'Lot on hold.','lot.release':'Lot released.','lot.recall':'Lot recalled.','recommendation.dismiss':'Suggestion dismissed.','stock.reverse':'Movement reversed.','user.save':'User saved.','category.save':'Category added.'};
const savedText = command => SAVED[command]||'Saved.';
function formDialog({title,description,fields=[],initial={},command,transform,submitLabel='Save',onSave,tabs,children=[],wide=false,done,more}) {
  const refs={},error=el('div',{className:'form-error',role:'alert'}),form=el('form',{className:'form-section'});let dialog;
  const build=defs=>el('div',{className:'form-grid'},defs.map(def=>{const node=field(def,initial[def.key]);refs[def.key]=node;return node;}));
  form.append(...children);
  if(tabs){if(fields.length)form.append(build(fields));const t=Tabs({items:tabs.map((tab,i)=>({id:`tab-${i}`,label:tab.label,content:stack([tab.description?text(tab.description):null,build(tab.fields)])}))});
    // "More options": the essentials stay on top, everything else waits behind one disclosure
    if(more){const box=el('details',{className:'form-more',open:!!more.open},[el('summary',{},more.label||'More options'),t]);form.append(box);form.addEventListener('invalid',e=>{if(box.contains(e.target))box.open=true;},true);}else form.append(t);}
  else form.append(build(fields));
  const save=Button({label:submitLabel,type:'submit',variant:'primary'}),cancel=Button({label:'Cancel',onClick:()=>dialog.dismiss()});
  form.append(error,el('div',{className:'form-actions'},[cancel,save]));
  form.addEventListener('submit',async event=>{event.preventDefault();error.textContent='';save.disabled=true;save.textContent='Saving…';try{let payload={};for(const [key,node]of Object.entries(refs))payload[key]=node.read();if(initial.id)Object.assign(payload,{id:initial.id,version:initial.version});if(transform)payload=await transform(payload);const result=command?await api.command(command,payload):await onSave(payload);if(result?.queued){Toast({message:'Awaiting server confirmation. Review the device queue before repeating this action.',tone:'warning'});}else if(result?.status==='failed'||result?.event?.status==='failed'||result?.exception)Toast({message:'Recorded with an exception. Review the result before proceeding.',tone:'warning'});else Toast(done?.(result,payload)||{message:command?savedText(command):'Done.'});dialog.dismiss();for(const drawer of document.querySelectorAll('dialog.pv-drawer[open]'))drawer.dismiss();await refresh();if(command&&onSave&&!result?.queued)await onSave(result,payload);}catch(err){if(err.status===401){await expireSession();return;}error.textContent=err.message||String(err);save.disabled=false;save.textContent=submitLabel;}});
  dialog=makeDialog({title,description,children:[form]});if(wide||tabs)dialog.classList.add('kura-editor');return {dialog,form,refs,error,save};
}
function reasonCommand(title,command,payload,extra=[]) { return formDialog({title,fields:[...extra,{key:'reason',label:'Reason',type:'textarea',required:true,wide:true}],command,transform:values=>({...payload,...values}),submitLabel:title}); }
async function execute(command,payload,label=savedText(command)) { try{const result=await api.command(command,payload);Toast({message:result?.queued?'Awaiting server confirmation. Review the device queue before repeating this action.':label,tone:result?.queued?'warning':'success'});await refresh();return result;}catch(error){if(error.status===401)await expireSession();else showError(error);return null;} }

