  form.addEventListener('submit',async e=>{e.preventDefault();submit.disabled=true;error.textContent='';try{const data=Object.fromEntries(Object.entries(refs).map(([k,n])=>[k,n.read()]));session=setup?await api.setup(data):await api.login(data);if(!session.user){renderAuth(!!session.setup_required);return;}await refresh(true);}catch(err){error.textContent=err.message;submit.disabled=false;}});
  app.replaceChildren(el('div',{className:'auth-page'},[el('section',{className:'auth-brand'},[brand(),stack([el('h1',{},'Inventory in order. Care uninterrupted.'),text('Know what you have, where it is, and what needs attention.','')]),el('div',{className:'auth-brand-details'},[text('Your inventory, in one place'),text('Receiving · Stock movements · Purchasing · Traceability')])]),el('main',{id:'main',className:'auth-form-area'},form)]));
