async function expireSession(){state={};session={user:null};for(const dialog of document.querySelectorAll('dialog[open]'))dialog.dismiss?.();main=null;await api.session().catch(()=>{});renderAuth();Toast({message:'Your session ended. Sign in again to continue.',tone:'info'});}
async function refresh(rebuild=false) {
  try{state=await api.state();offline=false;}catch(err){if(err.status===401){await expireSession();return;}const cached=await api.loadOfflineState();if(cached){state=cached;offline=true;}else throw err;}
  state.ledger=[...list('ledger')].sort((a,b)=>String(b.timestamp).localeCompare(String(a.timestamp)));
  if(rebuild||!main||!main.isConnected)renderShell();else{renderPage();renderStatus();}
  if(location.hash.startsWith('#at/'))takeDeepLink();
  if(!offline&&settingData('notifications').brief_push)publishBrief(state.planning?.brief);   // once a phone has the morning brief on
}
