  const header=el('header',{className:'kura-header'},[inline([Button({label:'Open navigation',icon:'list',iconOnly:true,variant:'ghost',className:'mobile-menu','aria-controls':'kura-navigation','aria-expanded':'false',onClick:e=>{const open=rail.classList.toggle('is-visible');e.currentTarget.setAttribute('aria-expanded',String(open));}}),brand()]),el('div',{className:'header-actions'},[searchButton,themeButton,UserAvatar({name:state.user?.name||session.user?.name||'User'}),el('div',{className:'account-label'},[el('strong',{},state.user?.name||session.user?.name||'User'),el('small',{},titleCase(state.user?.role||session.user?.role))]),Button({label:'Sign out',variant:'ghost',onClick:async()=>{try{await api.logout();await api.clearOfflineData();state={};main=null;renderAuth();}catch(e){showError(e);}}})])]);
