const isSafe = id => (state.controlled?.safes||[]).some(x=>x.location_id===id);
function qrLabelsDialog(locs){locs=locs.filter(Boolean);if(!locs.length)return;const labels=el('div',{className:'qr-labels'},locs.slice(0,120).map(l=>qrLabel(l,{kind:l.type==='kit'?'kit':isSafe(l.id)?'safe':'place',parentName:l.parent_id?locationName(l.parent_id):''})));
  const d=makeDialog({title:locs.length===1?`QR label · ${locs[0].name}`:'QR labels',description:'Stick one on each shelf, room, safe or cart. Scanning it in Kura — or with the iPhone Camera — sets where the device is, or opens the kit’s check.',children:[stack([labels,el('div',{className:'form-actions'},[Button({label:'Close',onClick:()=>d.dismiss()}),Button({label:locs.length===1?'Print label':`Print ${locs.length} labels`,icon:'download',variant:'primary',onClick:()=>{d.classList.add('printing');window.print();setTimeout(()=>d.classList.remove('printing'),500);}})])])]});d.classList.add('kura-editor');return d;}
/* A scanned label (#at/<id>): a kit opens its check; any other place becomes where this device is. */
function openAt(id){const loc=find('locations',id);if(!loc){Toast({message:'This label is for a location Kura doesn’t have any more.',tone:'warning'});return;}
  if(loc.type==='kit'){if(page!=='kits')navigate('kits');setTimeout(()=>kitSheet(planK(),id)||locationDrawer(loc),0);return;}
  setDeviceLocation(id);document.querySelectorAll('.kura-device-select').forEach(x=>{x.value=id;});
  Toast({message:`This device is in ${loc.name} now.`});locationDrawer(loc);}
function takeDeepLink(){const h=location.hash.slice(1);if(!h.startsWith('at/'))return false;const id=decodeURIComponent(h.slice(3));page=page&&!page.startsWith('at/')?page:'scan';history.replaceState(null,'','#'+page);if(main?.isConnected)renderPage();openAt(id);return true;}
const searchK = () => ({state,list,find,fmt,available,locationName,vendorName,navigate,itemDrawer,orderDrawer,locationDrawer,vendorDrawer,kitSheet:id=>kitSheet(planK(),id),makeDialog});
function search(initial=''){if(!state.user)return;return openSearch(searchK(),initial);}
// ⌘K / Ctrl+K anywhere; "/" when not typing in a field
window.addEventListener('keydown',e=>{if(!state.user||!main?.isConnected)return;const typing=e.target.closest?.('input,textarea,select,[contenteditable="true"]');
  if((e.metaKey||e.ctrlKey)&&!e.altKey&&e.key.toLowerCase()==='k'){e.preventDefault();search();}
  else if(e.key==='/'&&!typing&&!e.metaKey&&!e.ctrlKey&&!document.querySelector('dialog[open]')){e.preventDefault();search();}});
