  return rows.map((values,index)=>{if(values.length!==headers.length)throw new Error(`Row ${index+2} has ${values.length} cells; expected ${headers.length}.`);const result={};headers.forEach((key,j)=>{const value=values[j].trim();if(!value)return;if(numeric.has(key)){if(!Number.isFinite(Number(value)))throw new Error(`Row ${index+2}: ${key} is not a number.`);result[key]=Number(value);}else if(bool.has(key)){if(!['true','false','1','0','yes','no'].includes(value.toLowerCase()))throw new Error(`Row ${index+2}: ${key} must be true or false.`);result[key]=['true','1','yes'].includes(value.toLowerCase());}else if(['units','metadata','alternatives'].includes(key)){try{result[key]=JSON.parse(value);}catch{throw new Error(`Row ${index+2}: ${key} must be valid JSON.`);}}else if(key==='barcodes')result[key]=value.startsWith('[')?JSON.parse(value):value.split('|').map(s=>s.trim()).filter(Boolean);else result[key]=value;});if(result.base_unit&&!result.units)result.units={[result.base_unit]:1};return result;});
