function saveTextFile(filename,content,type='text/plain'){const url=URL.createObjectURL(new Blob([content],{type}));const a=el('a',{href:url,download:filename});document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function importDialog(){let preview=null,rows=null;const input=field({key:'file',label:'CSV file',type:'file'});input.control.accept='.csv,text/csv';const errors=el('div',{className:'form-error',role:'alert'}),results=el('div'),commit=Button({label:'Import reviewed items',variant:'primary',disabled:true,onClick:async()=>{commit.disabled=true;try{const result=await api.command('import.commit',{rows,preview_id:preview.preview_id});dialog.dismiss();Toast({message:result?.queued?'Awaiting server confirmation. Review the device queue before repeating this import.':`${fmt(result.count)} items imported.`,tone:result?.queued?'warning':'success'});await refresh();}catch(error){errors.textContent=error.message;commit.disabled=false;}}});
  const previewButton=Button({label:'Validate & preview',icon:'search',onClick:async()=>{errors.textContent='';previewButton.disabled=true;commit.disabled=true;try{if(!input.control.files[0])throw new Error('Choose a CSV file.');rows=parseCSV(await input.control.files[0].text());preview=await api.command('import.preview',{rows});if(preview?.queued)throw new Error('Preview confirmation is pending. Review the device queue, then validate again before importing.');results.replaceChildren(text(`${fmt(preview.count)} items reviewed. ${preview.errors?.length||0} validation problems.`),preview.valid?Table({caption:'Import preview',rows:(preview.rows||rows).slice(0,20),columns:[{label:'Item',key:'name'},{label:'SKU',key:'sku'},{label:'Base unit',key:'base_unit'},{label:'Category',key:'category'}]}):Table({caption:'Import problems',rows:preview.errors||[],columns:[{label:'Row',key:'row'},{label:'Problem',key:'message'}]}),text(preview.valid?'Preview shows up to 20 items. The entire file is validated before import.':'Correct the file, then validate again. No items were imported.'));commit.disabled=!preview.valid;}catch(error){errors.textContent=error.message;}finally{previewButton.disabled=false;}}});
  input.control.addEventListener('change',()=>{preview=null;rows=null;commit.disabled=true;results.replaceChildren();});const dialog=makeDialog({title:'Import inventory items',description:'Create items from a CSV file. Validate the complete dataset before committing. Opening balances are recorded separately.',children:[stack([text('Required columns: name, sku, base_unit. Optional columns use the item field names (category, vendor_id, minimum, reorder_point, target, unit_cost, barcodes, units, and others). Separate barcodes with |. Units may contain a quoted JSON object.'),Button({label:'Download CSV template',icon:'download',onClick:()=>saveTextFile('kura-item-import-template.csv','name,sku,base_unit,purchase_unit,consume_unit,category,barcodes,minimum,reorder_point,target,unit_cost\nExample product,EXAMPLE-001,each,each,each,Example,,0,0,0,0\n','text/csv')}),input,errors,results,el('div',{className:'form-actions'},[Button({label:'Cancel',onClick:()=>dialog.dismiss()}),previewButton,commit])])]});dialog.classList.add('kura-editor');}
function bulkDialog(ids){
  if(!ids.length){Toast({message:'Select items in the inventory table before bulk editing.',tone:'warning'});return;}let preview=null,changes=null,mode='simple';
  const fields=['category','vendor_id','minimum','reorder_point','target','safety_stock','lead_days','order_multiple','status','notes'];
  const numeric=new Set(['minimum','reorder_point','target','safety_stock','lead_days','order_multiple']);
  const choice=field({key:'field',label:'Field to change',type:'select',options:fields.map(key=>({value:key,label:key==='vendor_id'?'Preferred vendor':titleCase(key)}))},'category');
  const valueHost=el('div');let valueInput;
  const advanced=field({key:'changes',label:'Multiple field changes',type:'json',help:'Supported fields: '+fields.join(', ')},{category:''});
  const error=el('div',{className:'form-error',role:'alert'}),results=el('div');
  const apply=Button({label:'Apply reviewed changes',variant:'primary',disabled:true,onClick:async()=>{apply.disabled=true;try{const result=await api.command('bulk.apply',{kind:'item',ids,changes,preview_id:preview.preview_id});dialog.dismiss();Toast({message:result?.queued?'Awaiting server confirmation. Review the device queue before repeating this update.':`${fmt(result.count)} items updated.`,tone:result?.queued?'warning':'success'});await refresh();}catch(e){error.textContent=e.message;apply.disabled=false;}}});
  const invalidate=()=>{preview=null;apply.disabled=true;};
  function updateValue(){const key=choice.read();const def={key:'value',label:key==='vendor_id'?'New preferred vendor':'New '+titleCase(key).toLowerCase(),type:numeric.has(key)?'number':'text',min:0};if(key==='vendor_id'){def.type='select';def.options=options('vendors','No vendor');}if(key==='status'){def.type='select';def.options=['active','inactive'].map(x=>({value:x,label:titleCase(x)}));}if(key==='notes')def.type='textarea';valueInput=field(def);valueInput.control.addEventListener('input',invalidate);valueInput.control.addEventListener('change',invalidate);valueHost.replaceChildren(valueInput);invalidate();}
  choice.control.addEventListener('change',updateValue);advanced.control.addEventListener('input',invalidate);updateValue();
  const tabs=Tabs({items:[{id:'simple',label:'Change one field',content:stack([choice,valueHost])},{id:'advanced',label:'Advanced',content:advanced}],onChange:id=>{mode=id;invalidate();}});
  const review=Button({label:'Preview changes',onClick:async()=>{review.disabled=true;apply.disabled=true;error.textContent='';try{changes=mode==='simple'?{[choice.read()]:valueInput.read()}:advanced.read();preview=await api.command('bulk.preview',{kind:'item',ids,changes});if(preview?.queued)throw new Error('Preview confirmation is pending. Review the device queue, then preview again before applying.');results.replaceChildren(preview.valid?Alert({title:`${ids.length} items validated`,description:'Review the changes below before applying.',tone:'info'}):Alert({title:'Changes need correction',description:(preview.errors||[]).map(e=>`${e.row}: ${e.message}`).join('\n'),tone:'critical'}),codeView(preview.changes),Table({caption:'Affected items',rows:(preview.items||[]).slice(0,20),columns:[{label:'Item',key:'name'},{label:'SKU',key:'sku'},{label:'Category',key:'category'},{label:'Status',key:'status'}]}));apply.disabled=!preview.valid;}catch(e){error.textContent=e.message;}finally{review.disabled=false;}}});
  const dialog=makeDialog({title:`Bulk edit ${fmt(ids.length)} items`,description:'Update item settings in one reviewed action. Stock quantities and history cannot be changed here.',children:[stack([tabs,error,results,el('div',{className:'form-actions'},[Button({label:'Cancel',onClick:()=>dialog.dismiss()}),review,apply])])]});dialog.classList.add('kura-editor');
}

// CODE 128 subset B: printable ASCII, checksum and quiet zones. No remote barcode service.
const CODE128=['212222','222122','222221','121223','121322','131222','122213','122312','132212','221213','221312','231212','112232','122132','122231','113222','123122','123221','223211','221132','221231','213212','223112','312131','311222','321122','321221','312212','322112','322211','212123','212321','232121','111323','131123','131321','112313','132113','132311','211313','231113','231311','112133','112331','132131','113123','113321','133121','313121','211331','231131','213113','213311','213131','311123','311321','331121','312113','312311','332111','314111','221411','431111','111224','111422','121124','121421','141122','141221','112214','112412','122114','122411','142112','142211','241211','221114','413111','241112','134111','111242','121142','121241','114212','124112','124211','411212','421112','421211','212141','214121','412121','111143','111341','131141','114113','114311','411113','411311','113141','114131','311141','411131','211412','211214','211232','2331112'];
function barcodeSVG(value){if(!value||/[^\x20-\x7e]/.test(value)||value.length>60)return text('Barcode image requires 1–60 printable ASCII characters. Use the original manufacturer label.');const codes=[104,...Array.from(value,c=>c.charCodeAt(0)-32)];codes.push(codes.reduce((n,c,i)=>n+c*(i||1),0)%103,106);const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');let x=10;for(const code of codes){const pattern=CODE128[code];for(let i=0;i<pattern.length;i++){const width=Number(pattern[i]);if(i%2===0){const bar=document.createElementNS(svg.namespaceURI,'rect');for(const[k,v]of Object.entries({x,y:0,width,height:50,fill:'currentColor'}))bar.setAttribute(k,v);svg.append(bar);}x+=width;}}svg.setAttribute('viewBox',`0 0 ${x+10} 50`);svg.setAttribute('role','img');svg.setAttribute('aria-label',`Code 128 barcode ${value}`);return svg;}
function printLabels(items){if(!items.length){Toast({message:'Select one or more items to print labels.',tone:'warning'});return;}const labels=el('div',{className:'print-labels'},items.slice(0,100).map(i=>{const barcode=i.barcodes?.[0]||i.sku;return el('div',{className:'print-label'},[el('strong',{},i.name),barcodeSVG(barcode),el('div',{className:'mono'},barcode),el('small',{},`${i.sku} · ${i.base_unit}`)]);}));const dialog=makeDialog({title:'Inventory labels',description:`${Math.min(100,items.length)} labels. Check printed barcode readability with your scanner before operational use.`,children:[stack([labels,el('div',{className:'form-actions'},[Button({label:'Close',onClick:()=>dialog.dismiss()}),Button({label:'Print labels',icon:'download',variant:'primary',onClick:()=>{dialog.classList.add('printing');window.print();}})])])]});dialog.classList.add('kura-editor');}

