/* Instant start: draw the last screen this browser saw right away, marked as such, while the engine and sync start;
   then swap in the live data. Times are kept for Settings › System. */
let previewing=false;const startup={t0:performance.now(),first:null,ready:null};
function markFirst(){if(startup.first==null)startup.first=Math.round(performance.now()-startup.t0);}
async function start(){
  startup.t0=performance.now();startup.first=null;startup.ready=null;
  const quick=await api.quickStart();
  if(quick?.state&&quick.user&&!state.user){previewing=true;state={...quick.state};state.ledger=[...(state.ledger||[])].sort((a,b)=>String(b.timestamp).localeCompare(String(a.timestamp)));session={user:quick.user};try{renderShell();markFirst();document.body.classList.add('is-previewing');}catch{previewing=false;}}
  else app.replaceChildren(el('main',{id:'main',className:'kura-main'},[brand(),LoadingState({label:'Opening your inventory workspace…',rows:4})]));
  try{session=await api.session();if(!session.user){previewing=false;document.body.classList.remove('is-previewing');renderAuth(!!session.setup_required);return;}
    previewing=false;document.body.classList.remove('is-previewing');await refresh(true);markFirst();startup.ready=Math.round(performance.now()-startup.t0);
    try{localStorage.setItem('kura-startup',JSON.stringify({first:startup.first,ready:startup.ready,at:new Date().toISOString(),instant:!!quick}));}catch{}}
  catch(error){previewing=false;document.body.classList.remove('is-previewing');if(main?.isConnected&&state.user){Toast({message:error.message,tone:'critical'});return;}app.replaceChildren(el('main',{id:'main',className:'kura-main'},[brand(),Alert({title:'Kura could not open',description:error.message,tone:'critical',action:Button({label:'Try again',onClick:start})})]));}
}
